    broadcast(newMessage);
    res.status(201).json(newMessage);
  } catch (err) {
    console.error(err);
    res.status(500).send('Error saving message');
  }
});

app.listen(port, () => {
  console.log(`Backend server running at http://localhost:${port}`);
});
